begin
  case Kind of
    PaletteKind.DeepOcean:
    begin
      return 'Deep Ocean'
    end;
    PaletteKind.Ember:
    begin
      return 'Ember'
    end;
    PaletteKind.Aurora:
    begin
      return 'Aurora'
    end
  end
end;

function BandIndex(EscapeValue: real): integer;
begin
  return Clamp(Trunc(Frac(EscapeValue * 0.08) * 12.0), 0, 11)
end;

