program TaskGroupWorkers;

uses Std.Task, Std.Console;

function CheckConfiguration(Token: CancellationToken): result of boolean, string;
begin
  return Error('A required setting is missing')
end;

begin
  var Workers: TaskGroup := CreateTaskGroup();
  // Keep the group even when individual task handles are not needed.
  StartTaskInGroup(Workers, CheckConfiguration);
  StartTaskInGroup(Workers, procedure(Token: CancellationToken) begin
    var Stop: WaitCase := CancellationCase(Token, procedure() begin
      WriteLn('Background worker stopped')
    end);
    Select([Stop])
  end);
  // Close requests cooperative cancellation and waits for every registered worker.
  var Failures: array of TaskFailure := CloseTaskGroup(Workers);
  for Failure: TaskFailure in Failures do
  begin
    WriteLn(Failure.Message)
  end
end.

program GuardsExample;

uses Std.Console, Std.Conv;

type
  // The arm matches only when both the label and the guard are true.
  Shape = enum
    Circle(Radius: real);
    Rectangle(Width: real; Height: real);
    Point;
  end;

function Classify(N: integer): string;
begin
  case N of
    0:
    begin
      return 'zero'
    end;
    N if N > 0:
    begin
      return 'positive'
    end;
    N if N < 0:
    begin
      return 'negative'
    end
  end;

  return 'unknown'
end;

function DescribeShape(S: Shape): string;
begin
  case S of
    Shape.Circle(R) if R > 10.0:
    begin
      return ('Large circle (radius ' + RealToStr(R)) + ')'
    end;
    Shape.Circle(R):
    begin
      return ('Small circle (radius ' + RealToStr(R)) + ')'
    end;
    Shape.Rectangle(W, H) if W = H:
    begin
      return ('Square (' + RealToStr(W)) + ')'
    end;
    Shape.Rectangle(W, H):
    begin
      return ((('Rectangle (' + RealToStr(W)) + ' x ') + RealToStr(H)) + ')'
    end;
    Shape.Point:
    begin
      return 'Point'
    end
  end
end;

begin
  WriteLn('--- Integer guards ---');
  WriteLn(Classify(-7));
  WriteLn(Classify(0));
  WriteLn(Classify(42));
  WriteLn('--- Shape guards ---');
  WriteLn(DescribeShape(Shape.Circle(3.0)));
  WriteLn(DescribeShape(Shape.Circle(25.0)));
  WriteLn(DescribeShape(Shape.Rectangle(5.0, 5.0)));
  WriteLn(DescribeShape(Shape.Rectangle(4.0, 8.0)));
  WriteLn(DescribeShape(Shape.Point))
end.

// Build first: cargo build --release -p fpas-cli
// Baseline: target/release/fpas run this-file.fpas -- 2000000
// Guard: target/release/fpas run this-file.fpas -- 2000000 MAX_MILLIS

program VmArrayPushBenchmark;

uses Std.Args, Std.Arrays, Std.Console, Std.Conv, Std.Time;

const
  WarmupIterations: integer := 100000;

function RunPush(Iterations: integer): integer;
begin
  mutable var Values: array of integer := [];
  for Index: integer := 1 to Iterations do
  begin
    Std.Arrays.Push(Values, Index)
  end;

  return Std.Arrays.Length(Values)
end;

begin
  if (ParamCount() < 1) or (ParamCount() > 2) then
  begin
    panic('usage: array_push_benchmark.fpas -- ITERATIONS [MAX_MILLIS]')
  end;
  var Iterations: integer := StrToInt(ParamStr(0));
  if Iterations < 1 then
  begin
    panic('ITERATIONS must be positive')
  end;
  mutable var MaxMillis: integer := 0;
  if ParamCount() = 2 then
  begin
    MaxMillis := StrToInt(ParamStr(1));
    if MaxMillis < 1 then
    begin
      panic('MAX_MILLIS must be positive')
    end
  end;
  mutable var Length: integer := RunPush(WarmupIterations);
  var Started: integer := MonotonicMillis();
  Length := RunPush(Iterations);
  var Elapsed: integer := ElapsedMillis(Started);
  mutable var OpsPerSecond: integer := 0;
  if Elapsed > 0 then
  begin
    OpsPerSecond := (Iterations * 1000) div Elapsed
  end;

  WriteLn((('iterations: ' + IntToStr(Iterations)) + ', warm-up: ') + IntToStr(WarmupIterations));
  WriteLn(('elapsed: ' + IntToStr(Elapsed)) + ' ms');
  if Elapsed > 0 then
  begin
    WriteLn(('throughput: ' + IntToStr(OpsPerSecond)) + ' pushes/s')
  end
  else
  begin
    WriteLn('throughput: unavailable (elapsed time is 0 ms)')
  end;

  WriteLn('final length: ' + IntToStr(Length));
  if (MaxMillis > 0) and (Elapsed > MaxMillis) then
  begin
    panic(((('array-push benchmark regression: ' + IntToStr(Elapsed)) + ' ms exceeds limit ') + IntToStr(MaxMillis)) +
          ' ms')
  end
end.

// Measures short, empty, and full slices of long ASCII or Unicode strings.
program VmStringSubstringBenchmark;

uses Std.Args, Std.Console, Std.Conv, Std.Str, Std.Time;

function RunSlices(Text: string; UnitText: string; Iterations: integer): integer;
begin
  var Count: integer := Std.Str.Length(Text);
  var Width: integer := Std.Str.Length(UnitText);
  mutable var Matches: integer := 0;
  for Index: integer := 1 to Iterations do
  begin
    if Std.Str.Substring(Text, 0, Width) = UnitText then
    begin
      Matches := Matches + 1
    end;

    if Std.Str.Substring(Text, Count div 2, Width) = UnitText then
    begin
      Matches := Matches + 1
    end;

    if Std.Str.Substring(Text, Count - Width, Width) = UnitText then
    begin
      Matches := Matches + 1
    end;

    if Std.Str.Substring(Text, Count, 0) = '' then
    begin
      Matches := Matches + 1
    end;

    if Std.Str.Substring(Text, 0, Count) = Text then
    begin
      Matches := Matches + 1
    end
  end;

  return Matches
end;

begin
  if ParamCount() <> 2 then
  begin
    panic('usage: string_substring_benchmark.fpas -- ITERATIONS ascii|unicode')
  end;
  var Iterations: integer := StrToInt(ParamStr(0));
  if Iterations < 1 then
  begin
    panic('ITERATIONS must be positive')
  end;
  var Mode: string := ParamStr(1);
  if (Mode <> 'ascii') and (Mode <> 'unicode') then
  begin
    panic('mode must be ascii or unicode')
  end;
  mutable var UnitText: string := 'abcd';
  if Mode = 'unicode' then
  begin
    UnitText := 'aé😀界'
  end;
  var Text: string := Std.Str.RepeatStr(UnitText, 8192);
  if RunSlices(Text, UnitText, 100) <> 500 then
  begin
    panic('warmup substring mismatch')
  end;
  var Started: integer := MonotonicMillis();
  var Matches: integer := RunSlices(Text, UnitText, Iterations);
  var Elapsed: integer := ElapsedMillis(Started);
  if Matches <> Iterations * 5 then
  begin
    panic('substring result mismatch')
  end;

  WriteLn(('elapsed: ' + IntToStr(Elapsed)) + ' ms');
  WriteLn('matches: ' + IntToStr(Matches))
end.

// Buffered and streaming HTTP client orchestration.
unit Std.Http.Client;

uses
  Std.Arrays, Std.Http.Head, Std.Http.Headers, Std.Http.Io, Std.Http.Redirect, Std.Http.Stream,
  Std.Http.Types, Std.Http.Wire, Std.Net, Std.Net.Uri;

// Opens a TCP or verified TLS connection selected by URI scheme.
//
// Parameters:
// - `UriValue`: Parsed absolute request URI.
// - `TimeoutMillis`: Connection and TLS handshake timeout.
function OpenConnection(UriValue: Uri; TimeoutMillis: integer): result of Std.Net.Connection, string;
begin
  if UriValue.Scheme = 'http' then
  begin
    return Std.Net.Connect(UriValue.Host, UriValue.Port, TimeoutMillis)
  end;

  if UriValue.Scheme = 'https' then
  begin
    return Std.Net.ConnectTls(UriValue.Host, UriValue.Port, TimeoutMillis)
  end;

  return Error('Std.Http supports only http:// and https:// URLs')
end;

// Closes a connection while deliberately ignoring close errors.
//
// Parameters:
// - `Connection`: Connection to close.
procedure CloseQuietly(Connection: Std.Net.Connection);
begin
  case Std.Net.Close(Connection) of
    Ok(_):
    begin
    end;
    Error(_):
    begin
    end
  end
end;

// Sends one request without applying redirect policy.
//
// Parameters:
// - `RequestValue`: Complete request and its transport limits.
function OpenOnce(RequestValue: Request): result of StreamResponse, string;
begin
  mutable var UriValue: Uri := record
    Scheme := '';
    Host := '';
    Port := 0;
    Path := '';
  end;

  case Std.Net.Uri.Parse(RequestValue.Url) of
    Ok(Value):
    begin
      UriValue := Value
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end;
  mutable var Encoded: array of integer := [];
  case Std.Http.Wire.EncodeRequest(RequestValue, UriValue) of
    Ok(Value):
    begin
      Encoded := Value
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end;

  case OpenConnection(UriValue, RequestValue.TimeoutMillis) of
    Ok(Connection):
    begin
      case Std.Net.SetTimeout(Connection, RequestValue.TimeoutMillis) of
        Ok(Configured):
        begin
          if not Configured then
          begin
            CloseQuietly(Connection);
            return Error('Network timeout configuration failed')
          end
        end;
        Error(Message):
        begin
          CloseQuietly(Connection);
          return Error(Message)
        end
      end;

      case Std.Http.Io.WriteAll(Connection, Encoded) of
        Ok(Written):
        begin
        end;
        Error(Message):
        begin
          CloseQuietly(Connection);
          return Error(Message)
        end
      end;

      case Std.Http.Head.ReadFinal(Connection, RequestValue.MaxHeaderBytes, RequestValue.MaxResponseBytes) of
        Ok(FinalHead):
        begin
          case Std.Http.Stream.CreateBody(Connection, FinalHead.InitialBody, FinalHead.Head.Headers, Std.Http.Wire.ResponseHasBody(RequestValue.Method, FinalHead.Head.StatusCode), FinalHead.BytesReceived, RequestValue.MaxResponseBytes) of
            Ok(Body):
            begin
              return Ok(record
                StatusCode := FinalHead.Head.StatusCode;
                ReasonPhrase := FinalHead.Head.ReasonPhrase;
                Headers := FinalHead.Head.Headers;
                Body := Body;
              end)
            end;
            Error(Message):
            begin
              return Error(Message)
            end
          end
        end;
        Error(Message):
        begin
          CloseQuietly(Connection);
          return Error(Message)
        end
      end
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end
end;

// Opens the final response body after following bounded HTTP redirects.
//
// Parameters:
// - `RequestValue`: Complete request and its transport limits.
public function OpenStream(RequestValue: Request): result of StreamResponse, string;
begin
  if RequestValue.MaxHeaderBytes < 1 then
  begin
    return Error('HTTP MaxHeaderBytes must be positive')
  end;

  if RequestValue.MaxResponseBytes < 1 then
  begin
    return Error('HTTP MaxResponseBytes must be positive')
  end;

  if RequestValue.MaxRedirects < 0 then
  begin
    return Error('HTTP MaxRedirects must not be negative')
  end;
  mutable var Current: Request := RequestValue;
  mutable var Redirects: integer := 0;
  while true do
  begin
    case OpenOnce(Current) of
      Ok(ResponseValue):
      begin
        if Std.Http.Redirect.IsStatus(ResponseValue.StatusCode) then
        begin
          case Std.Http.Headers.Find(ResponseValue.Headers, 'Location') of
            Some(Location):
            begin
              if Redirects >= RequestValue.MaxRedirects then
              begin
                case Std.Http.Stream.CloseBody(ResponseValue.Body) of
                  Ok(_):
                  begin
                  end;
                  Error(_):
                  begin
                  end
                end;

                return Error('HTTP redirect count exceeds MaxRedirects')
              end;
              mutable var Next: Request := Current;
              case Std.Http.Redirect.NextRequest(Current, ResponseValue.StatusCode, Location) of
                Ok(Value):
                begin
                  Next := Value
                end;
                Error(Message):
                begin
                  case Std.Http.Stream.CloseBody(ResponseValue.Body) of
                    Ok(_):
                    begin
                    end;
                    Error(_):
                    begin
                    end
                  end;

                  return Error(Message)
                end
              end;

              case Std.Http.Stream.CloseBody(ResponseValue.Body) of
                Ok(_):
                begin
                end;
                Error(_):
                begin
                end
              end;

              Current := Next;
              Redirects := Redirects + 1
            end;
            None:
            begin
              return Ok(ResponseValue)
            end
          end
        end
        else
        begin
          return Ok(ResponseValue)
        end
      end;
      Error(Message):
      begin
        return Error(Message)
      end
    end
  end;

  return Error('HTTP redirect loop ended unexpectedly')
end;

// Sends one request, follows bounded redirects, and buffers the final body.
//
// Parameters:
// - `RequestValue`: Complete request and its transport limits.
public function Send(RequestValue: Request): result of Response, string;
begin
  case OpenStream(RequestValue) of
    Ok(StreamResponseValue):
    begin
      mutable var Chunks: array of array of integer := [];
      while true do
      begin
        case Std.Http.Stream.ReadBody(StreamResponseValue.Body, 65536) of
          Ok(Bytes):
          begin
            if Std.Arrays.Length(Bytes) = 0 then
            begin
              return Ok(record
                StatusCode := StreamResponseValue.StatusCode;
                ReasonPhrase := StreamResponseValue.ReasonPhrase;
                Headers := StreamResponseValue.Headers;
                Body := Std.Http.Io.JoinChunks(Chunks);
              end)
            end;

            Std.Arrays.Push(Chunks, Bytes)
          end;
          Error(Message):
          begin
            case Std.Http.Stream.CloseBody(StreamResponseValue.Body) of
              Ok(_):
              begin
              end;
              Error(_):
              begin
              end
            end;

            return Error(Message)
          end
        end
      end;

      return Error('HTTP response stream ended unexpectedly')
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end
end;

// Shared HTTP field validation and parsing.
unit Std.Http.Fields;

uses Std.Arrays, Std.Http.Method, Std.Http.Types, Std.Str;

// Reports whether an HTTP field value contains only permitted text characters.
//
// Parameters:
// - `Value`: Field value to validate.
public function IsValidValue(Value: string): boolean;
begin
  for Index: integer := 0 to Std.Str.Length(Value) - 1 do
  begin
    var Code: integer := Std.Str.Ord(Std.Str.CharAt(Value, Index));
    if ((Code < 32) and (Code <> 9)) or (Code = 127) then
    begin
      return false
    end
  end;

  return true
end;

// Parses validated HTTP fields after the first start-line in a text block.
//
// Parameters:
// - `Text`: Complete decoded message head.
// - `MessageKind`: Message label used in diagnostics.
public function Parse(Text: string; MessageKind: string): result of array of Header, string;
begin
  var Lines: array of string := Std.Str.Split(Text, #13 + #10);
  mutable var Headers: array of Header := [];
  for Index: integer := 1 to Std.Arrays.Length(Lines) - 1 do
  begin
    var Colon: integer := Std.Str.IndexOf(Lines[Index], ':');
    if Colon <= 0 then
    begin
      return Error((('Invalid HTTP ' + MessageKind) + ' header: ') + Lines[Index])
    end;
    var Name: string := Std.Str.Substring(Lines[Index], 0, Colon);
    var Value: string := Std.Str.Trim(Std.Str.Substring(Lines[Index], Colon + 1, (Std.Str.Length(Lines[Index]) - Colon) -
                                                                                 1));
    if not Std.Http.Method.IsValidToken(Name) then
    begin
      return Error((('Invalid HTTP ' + MessageKind) + ' header name: ') + Name)
    end;

    if not IsValidValue(Value) then
    begin
      return Error(('HTTP ' + MessageKind) + ' header contains an invalid control character')
    end;

    Std.Arrays.Push(Headers, Header.Create(Name, Value))
  end;

  return Ok(Headers)
end;

// Redirect URL resolution, header filtering, and method rewriting.
unit Std.Http.Redirect;

uses Std.Arrays, Std.Conv, Std.Http.Headers, Std.Http.Types, Std.Net.Uri, Std.Str;

// Formats a URI authority with a non-default port when required.
//
// Parameters:
// - `UriValue`: Parsed absolute URI.
function Authority(UriValue: Uri): string;
begin
  mutable var Host: string := UriValue.Host;
  if Std.Str.Contains(Host, ':') then
  begin
    Host := ('[' + Host) + ']'
  end;

  if ((UriValue.Scheme = 'http') and (UriValue.Port = 80)) or
     ((UriValue.Scheme = 'https') and (UriValue.Port = 443)) then
  begin
    return Host
  end;

  return (Host + ':') + Std.Conv.IntToStr(UriValue.Port)
end;

// Formats the scheme and authority portion of a URI.
//
// Parameters:
// - `UriValue`: Parsed absolute URI.
function Origin(UriValue: Uri): string;
begin
  return ((UriValue.Scheme + '://') + Authority(UriValue))
end;

// Removes a fragment from a URI reference.
//
// Parameters:
// - `Text`: URI reference that may contain a fragment.
function WithoutFragment(Text: string): string;
begin
  var Fragment: integer := Std.Str.IndexOf(Text, '#');
  if Fragment < 0 then
  begin
    return Text
  end;

  return Std.Str.Substring(Text, 0, Fragment)
end;

// Removes the query from a path-and-query value.
//
// Parameters:
// - `Path`: URI path that may contain a query.
function PathWithoutQuery(Path: string): string;
begin
  var Query: integer := Std.Str.IndexOf(Path, '?');
  if Query < 0 then
  begin
    return Path
  end;

  return Std.Str.Substring(Path, 0, Query)
end;

// Resolves dot segments in an absolute path while preserving its query.
//
// Parameters:
// - `PathAndQuery`: Absolute path with an optional query.
function NormalizePath(PathAndQuery: string): string;
begin
  mutable var Path: string := PathAndQuery;
  mutable var Query: string := '';
  var QueryStart: integer := Std.Str.IndexOf(PathAndQuery, '?');
  if QueryStart >= 0 then
  begin
    Path := Std.Str.Substring(PathAndQuery, 0, QueryStart);
    Query := Std.Str.Substring(PathAndQuery, QueryStart, Std.Str.Length(PathAndQuery) - QueryStart)
  end;
  var Parts: array of string := Std.Str.Split(Path, '/');
  mutable var Segments: array of string := [];
  for Index: integer := 0 to Std.Arrays.Length(Parts) - 1 do
  begin
    if (Parts[Index] = '') or (Parts[Index] = '.') then
    begin
      continue
    end;

    if Parts[Index] = '..' then
    begin
      if Std.Arrays.Length(Segments) > 0 then
      begin
        Segments := Std.Arrays.Slice(Segments, 0, Std.Arrays.Length(Segments) - 1)
      end;

      continue
    end;

    Std.Arrays.Push(Segments, Parts[Index])
  end;
  mutable var Output: string := '/';
  for Index: integer := 0 to Std.Arrays.Length(Segments) - 1 do
  begin
    if Index > 0 then
    begin
      Output := Output + '/'
    end;

    Output := Output + Segments[Index]
  end;

  return Output + Query
end;

// Resolves a redirect location against an absolute base URI.
//
// Parameters:
// - `Base`: Parsed URI of the current request.
// - `Location`: Location field value from the redirect response.
function Resolve(Base: Uri; Location: string): result of string, string;
begin
  if Std.Http.Headers.ContainsUnsafeText(Location) then
  begin
    return Error('HTTP redirect Location contains CR or LF')
  end;
  var Reference: string := WithoutFragment(Std.Str.Trim(Location));
  mutable var Target: string := '';
  if Reference = '' then
  begin
    Target := Origin(Base) + Base.Path
  end
  else if Std.Str.Contains(Reference, '://') then
  begin
    Target := Reference
  end
  else if Std.Str.StartsWith(Reference, '//') then
  begin
    Target := (Base.Scheme + ':') + Reference
  end
  else if Std.Str.StartsWith(Reference, '/') then
  begin
    Target := Origin(Base) + NormalizePath(Reference)
  end
  else if Std.Str.StartsWith(Reference, '?') then
  begin
    Target := (Origin(Base) + PathWithoutQuery(Base.Path)) + Reference
  end
  else
  begin
    var BasePath: string := PathWithoutQuery(Base.Path);
    var LastSlash: integer := Std.Str.LastIndexOf(BasePath, '/');
    mutable var Directory: string := '/';
    if LastSlash >= 0 then
    begin
      Directory := Std.Str.Substring(BasePath, 0, LastSlash + 1)
    end;

    Target := Origin(Base) + NormalizePath(Directory + Reference)
  end;

  case Std.Net.Uri.Parse(Target) of
    Ok(_):
    begin
      return Ok(Target)
    end;
    Error(Message):
    begin
      return Error('Invalid HTTP redirect Location: ' + Message)
    end
  end
end;

// Reports whether two URIs have the same scheme, host, and port.
//
// Parameters:
// - `Left`: First parsed URI.
// - `Right`: Second parsed URI.
function SameOrigin(Left: Uri; Right: Uri): boolean;
begin
  return ((Std.Str.ToLower(Left.Scheme) = Std.Str.ToLower(Right.Scheme)) and (Std.Str.ToLower(Left.Host) = Std.Str.ToLower(Right.Host))) and
         (Left.Port = Right.Port)
end;

// Removes sensitive or entity fields required by redirect policy.
//
// Parameters:
// - `Headers`: Current request fields.
// - `CrossOrigin`: Whether the redirect changes origin.
// - `DropBody`: Whether redirect semantics discard the request body.
function FilterHeaders(Headers: array of Header; CrossOrigin: boolean; DropBody: boolean): array of Header;
begin
  mutable var Output: array of Header := [];
  for Index: integer := 0 to Std.Arrays.Length(Headers) - 1 do
  begin
    var Name: string := Headers[Index].Name;
    if CrossOrigin and
       ((Std.Http.Headers.IsName(Name, 'Authorization') or Std.Http.Headers.IsName(Name, 'Proxy-Authorization')) or Std.Http.Headers.IsName(Name, 'Cookie')) then
    begin
      continue
    end;

    if DropBody and
       (Std.Http.Headers.IsName(Name, 'Content-Type') or Std.Http.Headers.IsName(Name, 'Content-Encoding')) then
    begin
      continue
    end;

    Std.Arrays.Push(Output, Headers[Index])
  end;

  return Output
end;

// Reports whether a status code uses the automatic redirect policy.
//
// Parameters:
// - `StatusCode`: HTTP response status code.
public function IsStatus(StatusCode: integer): boolean;
begin
  return (((StatusCode = 301) or (StatusCode = 302)) or (StatusCode = 303)) or
         ((StatusCode = 307) or (StatusCode = 308))
end;

// Builds the next request from one redirect response.
//
// Parameters:
// - `Current`: Request that received the redirect response.
// - `StatusCode`: Redirect response status code.
// - `Location`: Location field value from the redirect response.
public function NextRequest(Current: Request; StatusCode: integer; Location: string): result of Request, string;
begin
  mutable var Base: Uri := record
    Scheme := '';
    Host := '';
    Port := 0;
    Path := '';
  end;

  case Std.Net.Uri.Parse(Current.Url) of
    Ok(Value):
    begin
      Base := Value
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end;
  mutable var Target: string := '';
  case Resolve(Base, Location) of
    Ok(Value):
    begin
      Target := Value
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end;
  mutable var TargetUri: Uri := Base;
  case Std.Net.Uri.Parse(Target) of
    Ok(Value):
    begin
      TargetUri := Value
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end;
  var DropBody: boolean := ((StatusCode = 303) and (Current.Method <> 'HEAD')) or
                           (((StatusCode = 301) or (StatusCode = 302)) and (Current.Method = 'POST'));
  mutable var Output: Request := Current;
  Output.Url := Target;
  Output.Headers := FilterHeaders(Current.Headers, not SameOrigin(Base, TargetUri), DropBody);
  if DropBody then
  begin
    Output.Method := 'GET';
    Output.Body := []
  end;

  return Ok(Output)
end;

unit Std.Tui.Chrome.Button;

uses Std.Tui.Ids.Action, Std.Tui.Ids.ControlId;

