unit Std.Tui.Layout.AlignmentBounds;

uses Std.Tui.Geometry.Rect, Std.Tui.Layout.Alignment, Std.Tui.Layout.MeasureResult;

function TuiAlignmentBoundsMin(Left: integer; Right: integer): integer;
begin
  if Left < Right then
  begin
    return Left
  end;

  return Right
end;

function TuiAlignmentBoundsMax(Left: integer; Right: integer): integer;
begin
  if Left > Right then
  begin
    return Left
  end;

  return Right
end;

function TuiAlignmentBoundsExtent(
  Minimum: integer;
  Preferred: integer;
  Maximum: integer;
  Available: integer;
  Alignment: TuiAlignmentKind
): integer;
begin
  mutable var Extent: integer := Preferred;
  if Alignment = TuiAlignmentKind.Fill then
  begin
    Extent := TuiAlignmentBoundsMin(Available, Maximum)
  end;

  Extent := TuiAlignmentBoundsMax(Minimum, Extent);
  if Available >= Minimum then
  begin
    Extent := TuiAlignmentBoundsMin(Extent, Available)
  end;

  return Extent
end;

function TuiAlignmentBoundsOffset(Available: integer; Extent: integer; Alignment: TuiAlignmentKind): integer;
begin
  case Alignment of
    TuiAlignmentKind.Leading:
    begin
      return 0
    end;
    TuiAlignmentKind.Center:
    begin
      return (Available - Extent) div 2
    end;
    TuiAlignmentKind.Trailing:
    begin
      return Available - Extent
    end;
    TuiAlignmentKind.Fill:
    begin
      return 0
    end
  end;

  return 0
end;

public type
  // Resolves one measured element into an aligned rectangle within an allocated area.
  TuiAlignmentBounds = record
    // Applies independent alignment and size limits on both axes.
    //
    // Parameters:
    // - `Measured`: Measured minimum, preferred, and maximum sizes.
    // - `Alignment`: Alignment applied within the available area.
    // - `Area`: Available layout rectangle.
    public static function Resolve(Measured: TuiMeasureResult; Alignment: TuiAlignment; Area: TuiRect): TuiRect;
    begin
      var Width: integer := TuiAlignmentBoundsExtent(Measured.Minimum.Width, Measured.Preferred.Width, Measured.Maximum.Width, Area.Width, Alignment.Horizontal);
      var Height: integer := TuiAlignmentBoundsExtent(Measured.Minimum.Height, Measured.Preferred.Height, Measured.Maximum.Height, Area.Height, Alignment.Vertical);
      return TuiRect.Create(Area.X +
                            TuiAlignmentBoundsOffset(Area.Width, Width, Alignment.Horizontal), Area.Y +
                                                                                               TuiAlignmentBoundsOffset(Area.Height, Height, Alignment.Vertical), Width, Height)
    end;
  end;

unit Std.Tui.Layout.MeasureConstraint;

public type
  // Whether a measure axis is unbounded or capped.
  TuiMeasureConstraintKind = enum
    // Represents the `Unbounded` variant of `TuiMeasureConstraintKind`.
    Unbounded;
    // Represents the `AtMost` variant of `TuiMeasureConstraintKind`.
    AtMost;
  end;

function TuiMeasureConstraintRequireNonNegative(Value: integer): integer;
begin
  if Value < 0 then
  begin
    panic('Tui measure constraint limit must not be negative')
  end;

  return Value
end;

public type
  // One-axis measurement constraint.
  TuiMeasureConstraint = record
    // Variant kind represented by the value.
    public Kind: TuiMeasureConstraintKind;
    // Maximum extent of a bounded constraint.
    public Limit: integer;

    // Creates an unbounded axis constraint.
    public static function Unbounded(): TuiMeasureConstraint;
    begin
      return record
        Kind := TuiMeasureConstraintKind.Unbounded;
        Limit := 0;
      end
    end;

    // Creates a non-negative upper bound.
    //
    // Parameters:
    // - `Limit`: Upper bound applied by the constraint.
    public static function AtMost(Limit: integer): TuiMeasureConstraint;
    begin
      return record
        Kind := TuiMeasureConstraintKind.AtMost;
        Limit := TuiMeasureConstraintRequireNonNegative(Limit);
      end
    end;

    // Returns whether the constraint has an upper bound.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function IsBounded(Self: TuiMeasureConstraint): boolean;
    begin
      return Self.Kind = TuiMeasureConstraintKind.AtMost
    end;
  end;

unit Std.Tui.Layout.MeasureResult;

uses Std.Tui.Geometry.Size;

procedure TuiMeasureResultRequireOrdered(Minimum: TuiSize; Preferred: TuiSize; Maximum: TuiSize);
begin
  if (Minimum.Width > Preferred.Width) or (Minimum.Height > Preferred.Height) then
  begin
    panic('Tui measure result minimum size must not exceed preferred size')
  end;

  if (Preferred.Width > Maximum.Width) or (Preferred.Height > Maximum.Height) then
  begin
    panic('Tui measure result preferred size must not exceed maximum size')
  end
end;

public type
  // Minimum, preferred, and maximum extents for one element.
  TuiMeasureResult = record
    // Minimum value or size.
    public Minimum: TuiSize;
    // Preferred size.
    public Preferred: TuiSize;
    // Maximum value or size.
    public Maximum: TuiSize;

    // Creates an ordered measure result.
    //
    // Parameters:
    // - `Minimum`: Minimum accepted value or extent.
    // - `Preferred`: Preferred size or focus identifier.
    // - `Maximum`: Maximum accepted value or extent.
    public static function Create(Minimum: TuiSize; Preferred: TuiSize; Maximum: TuiSize): TuiMeasureResult;
    begin
      TuiMeasureResultRequireOrdered(Minimum, Preferred, Maximum);
      return record
        Minimum := Minimum;
        Preferred := Preferred;
        Maximum := Maximum;
      end
    end;

    // Creates a fixed measure where all three sizes match.
    //
    // Parameters:
    // - `Size`: Size in terminal cells.
    public static function Fixed(Size: TuiSize): TuiMeasureResult;
    begin
      return TuiMeasureResult.Create(Size, Size, Size)
    end;
  end;

// Cell-grid painting.
unit Std.Tui.Rendering.CellGrid;

uses
  Std.Tui.Chrome.CellGrid, Std.Tui.Geometry.Point, Std.Tui.Geometry.Rect, Std.Tui.Rendering.Canvas;

// Paints the visible part of a row-major terminal cell grid.
//
// Parameters:
// - `Canvas`: Canvas that receives the drawing operation.
// - `Bounds`: Rectangle affected by the operation.
// - `Grid`: Cell grid to paint.
public procedure TuiPaintCellGrid(Canvas: TuiCanvas; Bounds: TuiRect; Grid: TuiCellGrid);
begin
  mutable var Width: integer := Grid.Width;
  mutable var Height: integer := Grid.Height;
  if Width > Bounds.Width then
  begin
    Width := Bounds.Width
  end;

  if Height > Bounds.Height then
  begin
    Height := Bounds.Height
  end;

  for Y: integer := 0 to Height - 1 do
  begin
    for X: integer := 0 to Width - 1 do
    begin
      Canvas.PutCell(TuiPoint.Create(Bounds.X + X, Bounds.Y + Y), Grid.Cells[(Y * Grid.Width) + X])
    end
  end
end;

unit Std.Tui.Runtime.Routing.Input;

uses
  Std.Arrays, Std.Console, Std.Str, Std.Tui.Chrome.Input, Std.Tui.Ids.ControlId,
  Std.Tui.Runtime.Msg;

function TuiInputPreviousWord(Text: string; Caret: integer): integer;
begin
  mutable var Index: integer := Caret;
  while Index > 0 do
  begin
    if Std.Str.CharAt(Text, Index - 1) = ' ' then
    begin
      Index := Index - 1
    end
    else
    begin
      break
    end
  end;

  while Index > 0 do
  begin
    if Std.Str.CharAt(Text, Index - 1) <> ' ' then
    begin
      Index := Index - 1
    end
    else
    begin
      break
    end
  end;

  return Index
end;

function TuiInputNextWord(Text: string; Caret: integer): integer;
begin
  mutable var Index: integer := Caret;
  while Index < Std.Str.Length(Text) do
  begin
    if Std.Str.CharAt(Text, Index) <> ' ' then
    begin
      Index := Index + 1
    end
    else
    begin
      break
    end
  end;

  while Index < Std.Str.Length(Text) do
  begin
    if Std.Str.CharAt(Text, Index) = ' ' then
    begin
      Index := Index + 1
    end
    else
    begin
      break
    end
  end;

  return Index
end;

function TuiInputHistoryIndex(Input: TuiInputSpec): integer;
begin
  if Input.Text = Input.HistoryDraft then
  begin
    return -1
  end;

  for Index: integer := Std.Arrays.Length(Input.History) - 1 downto 0 do
  begin
    if Input.History[Index] = Input.Text then
    begin
      return Index
    end
  end;

  return -1
end;

function TuiInputHistoryKey(Input: TuiInputSpec; Key: Std.Console.KeyEvent): option of TuiMsg;
begin
  if Std.Arrays.Length(Input.History) = 0 then
  begin
    return None
  end;
  var Index: integer := TuiInputHistoryIndex(Input);
  if Key.kind = Std.Console.KeyKind.Up then
  begin
    if Index < 0 then
    begin
      var Text: string := Input.History[Std.Arrays.Length(Input.History) - 1];
      return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Text, Std.Str.Length(Text)))
    end;

    if Index > 0 then
    begin
      var Text: string := Input.History[Index - 1];
      return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Text, Std.Str.Length(Text)))
    end;

    return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Input.Text, Input.Caret))
  end;

  if Key.kind = Std.Console.KeyKind.Down then
  begin
    if Index < 0 then
    begin
      return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Input.Text, Input.Caret))
    end;

    if Index < Std.Arrays.Length(Input.History) - 1 then
    begin
      var Text: string := Input.History[Index + 1];
      return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Text, Std.Str.Length(Text)))
    end;

    return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Input.HistoryDraft, Std.Str.Length(Input.HistoryDraft)))
  end;

  return None
end;

// Routes one key when the supplied input owns focus.
//
// Parameters:
// - `Input`: Controlled input specification.
// - `Target`: Target control identifier.
// - `Key`: Console key event to route or match.
public function TuiRouteInputKey(Input: TuiInputSpec; Target: TuiControlId; Key: Std.Console.KeyEvent): option of TuiMsg;
begin
  if Input.Id.Value <> Target.Value then
  begin
    return None
  end;

  if ((Key.kind = Std.Console.KeyKind.Character) and not Key.ctrl) and
     (not Key.alt and not Key.meta) then
  begin
    return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Std.Str.Insert(Input.Text, Input.Caret, Key.ch), Input.Caret +
                                                                                                                  Std.Str.Length(Key.ch)))
  end;

  if ((Key.kind = Std.Console.KeyKind.Space) and not Key.ctrl) and (not Key.alt and not Key.meta) then
  begin
    return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Std.Str.Insert(Input.Text, Input.Caret, ' '), Input.Caret +
                                                                                                               1))
  end;

  if (Key.kind = Std.Console.KeyKind.Backspace) and (Input.Caret > 0) then
  begin
    mutable var Start: integer := Input.Caret - 1;
    if Key.ctrl then
    begin
      Start := TuiInputPreviousWord(Input.Text, Input.Caret)
    end;

    return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Std.Str.Delete(Input.Text, Start, Input.Caret -
                                                                                                   Start), Start))
  end;

  if (Key.kind = Std.Console.KeyKind.Delete) and (Input.Caret < Std.Str.Length(Input.Text)) then
  begin
    mutable var EndIndex: integer := Input.Caret + 1;
    if Key.ctrl then
    begin
      EndIndex := TuiInputNextWord(Input.Text, Input.Caret)
    end;

    return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Std.Str.Delete(Input.Text, Input.Caret, EndIndex -
                                                                                                         Input.Caret), Input.Caret))
  end;

  if (Key.kind = Std.Console.KeyKind.Left) and (Input.Caret > 0) then
  begin
    mutable var Caret: integer := Input.Caret - 1;
    if Key.ctrl then
    begin
      Caret := TuiInputPreviousWord(Input.Text, Input.Caret)
    end;

    return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Input.Text, Caret))
  end;

  if (Key.kind = Std.Console.KeyKind.Right) and (Input.Caret < Std.Str.Length(Input.Text)) then
  begin
    mutable var Caret: integer := Input.Caret + 1;
    if Key.ctrl then
    begin
      Caret := TuiInputNextWord(Input.Text, Input.Caret)
    end;

    return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Input.Text, Caret))
  end;

  if Key.kind = Std.Console.KeyKind.Home then
  begin
    return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Input.Text, 0))
  end;

  if Key.kind = Std.Console.KeyKind.EndKey then
  begin
    return Some(TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Input.Text, Std.Str.Length(Input.Text)))
  end;

  if (Key.kind = Std.Console.KeyKind.Up) or (Key.kind = Std.Console.KeyKind.Down) then
  begin
    return TuiInputHistoryKey(Input, Key)
  end;

  return None
end;

program NoteTuiWorkflowTest;

uses Notes.Model, Notes.Update, Notes.View, Std.Arrays, Std.Fs, Std.Str, Std.Test, Std.Tui;

function ScreenContains(Snapshot: TuiSurfaceSnapshot; Text: string): boolean;
begin
  for Row: integer := 0 to Snapshot.Height - 1 do
  begin
    if Std.Str.Contains(Snapshot.LineAt(Row), Text) then
    begin
      return true
    end
  end;

  return false
end;

function MakeKey(Kind: TuiKeyKind): TuiKeyEvent;
begin
  return record
    kind := Kind;
    ch := '';
    shift := false;
    ctrl := false;
