  AssertTrue(Surface.CellAt(GoX, 1).Role = TuiStyleRole.ButtonSelectedShortcut);
  AssertTrue(Surface.CellAt(OkX, 2).Role = TuiStyleRole.ButtonDefaultShortcut);
  AssertTrue(Surface.CellAt(StopX, 3).Role = TuiStyleRole.ButtonDisabled);
  App.Close()
end.

program TuiCellPaletteValuesTest;

uses Std.Test, Std.Tui;

begin
  var RgbValue: TuiColor := TuiColor.FromRgb(10, 20, 30);
  AssertTrue(RgbValue.Kind = TuiColorKind.Rgb);
  AssertEquals(20, RgbValue.Green);
  var Plain: TuiStyle := TuiStyle.FromColors(RgbValue, TuiColor.FromRgb(1, 2, 3));
  AssertFalse(Plain.Bold);
  var Styled: TuiCell := TuiCell.Styled('X', Plain);
  AssertEquals('X', Styled.Glyph);
  AssertEquals(1, Styled.Width());
  case Styled.ConcreteStyle of
    Some(Concrete):
    begin
      AssertEquals(20, Concrete.Foreground.Green)
    end;
    None:
    begin
      panic('expected concrete cell style')
    end
  end;
  var Palette: TuiPalette := TuiPalette.Default();
  AssertTrue(Palette.ForRole(TuiStyleRole.Normal).Foreground.Kind = TuiColorKind.Rgb);
  AssertEquals(201, Palette.ForRole(TuiStyleRole.Normal).Foreground.Red);
  AssertEquals(13, Palette.ForRole(TuiStyleRole.Normal).Background.Red);
  AssertEquals(88, Palette.ForRole(TuiStyleRole.Accent).Foreground.Red);
  AssertEquals(31, Palette.ForRole(TuiStyleRole.Selected).Background.Red);
  AssertEquals(63, Palette.ForRole(TuiStyleRole.GaugeFill).Foreground.Red);
  AssertEquals(48, Palette.ForRole(TuiStyleRole.Rule).Foreground.Red);
  var Custom: TuiStyle := TuiStyle.FromColors(TuiColor.FromRgb(1, 2, 3), RgbValue);
  var Updated: TuiPalette := Palette.WithRole(TuiStyleRole.Warning, Custom);
  AssertEquals(2, Updated.ForRole(TuiStyleRole.Warning).Foreground.Green);
  AssertEquals(210, Palette.ForRole(TuiStyleRole.Warning).Foreground.Red)
end.

program TuiHierarchicalMenuTest;

uses Std.Arrays, Std.Str, Std.Test, Std.Tui;

type
  MenuModel = record
    Focus: integer;
    Menu: TuiMenuState;
    Actions: array of integer;
  end;

function MakeKey(Kind: TuiKeyKind; Character: string; Ctrl: boolean; Alt: boolean): TuiKeyEvent;
begin
  return record
    kind := Kind;
    ch := Character;
    shift := false;
    ctrl := Ctrl;
    alt := Alt;
    meta := false;
  end
end;

function FindGlyph(Snapshot: TuiSurfaceSnapshot; Glyph: string): TuiPoint;
begin
  for Y: integer := 0 to Snapshot.Height - 1 do
  begin
    var X: integer := Std.Str.IndexOf(Snapshot.LineAt(Y), Glyph);
    if X >= 0 then
    begin
      return TuiPoint.Create(X, Y)
    end
  end;

  panic('glyph not found in menu snapshot: ' + Glyph)
end;

procedure AssertActive(Menu: TuiMenuState; Expected: integer);
begin
  case Menu.Active of
    Some(Id):
    begin
      AssertEquals(Expected, Id.Value)
    end;
    None:
    begin
      Fail('Expected an active menu node.')
    end
  end
end;

function MenuNodes(): array of TuiMenuNode;
begin
  var FileId: TuiMenuNodeId := TuiMenuNodeId.Create(1);
  var OptionsId: TuiMenuNodeId := TuiMenuNodeId.Create(2);
  var ThemeId: TuiMenuNodeId := TuiMenuNodeId.Create(5);
  return [
           TuiMenuNodeBuilders.Submenu(FileId, None, 'File', 'F'),
           TuiMenuNodeBuilders.Submenu(OptionsId, None, 'Options', 'O'),
           TuiMenuNodeBuilders.CommandWithShortcut(TuiMenuNodeId.Create(3), Some(FileId), 'Open', 'O', TuiAction.Create(10), TuiKeyGesture.Create(TuiKeyKind.Character, 'o', false, true, false, false, 'Ctrl+O')),
           TuiMenuNodeBuilders.Separator(TuiMenuNodeId.Create(4), FileId),
           TuiMenuNodeBuilders.Submenu(ThemeId, Some(OptionsId), 'Theme', 'T'),
           TuiMenuNodeBuilders.Command(TuiMenuNodeId.Create(6), Some(ThemeId), 'Dark', 'D', TuiAction.Create(20))
         ]
end;

function ViewMenu(State: MenuModel): TuiElement;
begin
  return TuiElementBuilders.MakeDesktop(Some(TuiControlId.Create(State.Focus)), [
                                                                                  TuiElementBuilders.MakeMenu(TuiControlId.Create(100), MenuNodes(), State.Menu, TuiAction.Create(101))
                                                                                ])
end;

function UpdateMenu(State: MenuModel; Msg: TuiMsg; Cmd: TuiCmdOutput): MenuModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.FocusChanged(Previous, Current):
    begin
      case Current of
        Some(Id):
        begin
          return record
            Focus := Id.Value;
            Menu := State.Menu;
            Actions := State.Actions;
          end
        end;
        None:
        begin
          return State
        end
      end
    end;
    TuiMsg.MenuChanged(Source, Action, Menu):
    begin
      return record
        Focus := State.Focus;
        Menu := Menu;
        Actions := State.Actions;
      end
    end;
    TuiMsg.Action(Source, Action):
    begin
      return record
        Focus := State.Focus;
        Menu := State.Menu;
        Actions := Std.Arrays.Concat(State.Actions, [Action.Value]);
      end
    end
    else
    begin
      return State
    end
  end
end;

begin
  mutable var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(40, 10));
  mutable var Model: MenuModel := record
    Focus := 100;
    Menu := TuiMenuState.Closed();
    Actions := [];
  end;

  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 0, 0);
  AssertTrue(App.SurfaceSnapshot().CellAt(7, 0).Role = TuiStyleRole.MenuShortcut);
  AssertTrue(App.SurfaceSnapshot().CellAt(11, 0).Role = TuiStyleRole.MenuNormal);
  var ClosedFileAt: TuiPoint := FindGlyph(App.SurfaceSnapshot(), 'File');
  App.InjectPointerForTest(TuiPointerEvent.Create(TuiPointerAction.Move, TuiPointerButton.NoButton, ClosedFileAt));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  AssertFalse(Model.Menu.Open);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.F10, '', false, false));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  AssertTrue(Model.Menu.Open);
  AssertTrue(Std.Str.Contains(App.SurfaceSnapshot().LineAt(2), 'Open'));
  AssertFalse(App.SurfaceSnapshot().CellAt(16, 2).Glyph = '░');
  AssertFalse(App.SurfaceSnapshot().CellAt(2, 5).Glyph = '░');
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Down, '', false, false));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Enter, '', false, false));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 2, 0);
  AssertEquals(1, Std.Arrays.Length(Model.Actions));
  AssertEquals(10, Model.Actions[0]);
  AssertFalse(Model.Menu.Open);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Character, 'o', true, false));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 2, 0);
  AssertEquals(2, Std.Arrays.Length(Model.Actions));
  AssertEquals(10, Model.Actions[1]);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Character, 'o', false, true));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Down, '', false, false));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Right, '', false, false));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Down, '', false, false));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Enter, '', false, false));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 2, 0);
  AssertEquals(3, Std.Arrays.Length(Model.Actions));
  AssertEquals(20, Model.Actions[2]);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.F10, '', false, false));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  var OptionsAt: TuiPoint := FindGlyph(App.SurfaceSnapshot(), 'Options');
  App.InjectPointerForTest(TuiPointerEvent.Create(TuiPointerAction.Move, TuiPointerButton.NoButton, OptionsAt));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  AssertActive(Model.Menu, 2);
  var ThemeAt: TuiPoint := FindGlyph(App.SurfaceSnapshot(), 'Theme');
  App.InjectPointerForTest(TuiPointerEvent.Create(TuiPointerAction.Move, TuiPointerButton.NoButton, ThemeAt));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  AssertActive(Model.Menu, 5);
  var DarkAt: TuiPoint := FindGlyph(App.SurfaceSnapshot(), 'Dark');
  App.InjectPointerForTest(TuiPointerEvent.Create(TuiPointerAction.Move, TuiPointerButton.NoButton, DarkAt));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  AssertActive(Model.Menu, 6);
  AssertFalse(App.SurfaceSnapshot().CellAt(DarkAt.X + 6, DarkAt.Y).Glyph = '░');
  AssertFalse(App.SurfaceSnapshot().CellAt(DarkAt.X, DarkAt.Y + 2).Glyph = '░');
  AssertEquals(3, Std.Arrays.Length(Model.Actions));
  App.InjectPointerForTest(TuiPointerEvent.Create(TuiPointerAction.Move, TuiPointerButton.NoButton, TuiPoint.Create(39, 9)));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 1, 0);
  AssertTrue(Model.Menu.Open);
  AssertActive(Model.Menu, 6);
  AssertEquals(3, Std.Arrays.Length(Model.Actions));
  App.InjectPointerForTest(TuiPointerEvent.Create(TuiPointerAction.Down, TuiPointerButton.Left, DarkAt));
  Model := App.RunIterations(Model, UpdateMenu, ViewMenu, 2, 0);
  AssertFalse(Model.Menu.Open);
  AssertEquals(4, Std.Arrays.Length(Model.Actions));
  AssertEquals(20, Model.Actions[3]);
  App.Close()
end.

program TuiListSnapshotTest;

uses Std.Str, Std.Test, Std.Tui;

type
  ListModel = record
    Selected: integer;
  end;

function ViewList(State: ListModel): TuiElement;
begin
  return TuiElementBuilders.MakeDesktop(Some(TuiControlId.Create(1)), [
                                                                        TuiElementBuilders.MakePanel('Host', [
                                                                                                               TuiElementBuilders.MakeList(TuiControlId.Create(1), ['Alpha', 'Beta', 'Gamma'], State.Selected, TuiAction.Create(5))
                                                                                                             ])
                                                                      ])
end;

function UpdateList(State: ListModel; Msg: TuiMsg; Cmd: TuiCmdOutput): ListModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.SelectionChanged(Source, Action, Selected):
    begin
      return record
        Selected := Selected;
      end
    end
    else
    begin
      return State
    end
  end
end;

begin
  mutable var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(24, 8));
  mutable var Model: ListModel := record
    Selected := 1;
  end;

  Model := App.RunIterations(Model, UpdateList, ViewList, 0, 0);
  AssertTrue(Std.Str.Contains(App.SurfaceSnapshot().LineAt(1), '  Alpha'));
  AssertTrue(Std.Str.Contains(App.SurfaceSnapshot().LineAt(2), '> Beta'));
  AssertTrue(Std.Str.Contains(App.SurfaceSnapshot().LineAt(3), '  Gamma'));
  App.Close()
end.

program TuiStatusLineKeyboardTest;

uses Std.Arrays, Std.Test, Std.Tui;

type
  StatusModel = record
    Focus: integer;
    Actions: array of integer;
  end;

function MakeKey(Kind: TuiKeyKind): TuiKeyEvent;
begin
  return record
    kind := Kind;
    ch := '';
    shift := false;
    ctrl := false;
    alt := false;
    meta := false;
  end
end;

function ViewStatus(State: StatusModel): TuiElement;
begin
  return TuiElementBuilders.MakeDesktop(Some(TuiControlId.Create(State.Focus)), [
                                                                                  TuiElementBuilders.MakeStatusLine([
                                                                                                                      TuiStatusItemBuilders.MakeHint('Ready'),
                                                                                                                      TuiStatusItemBuilders.MakeDisabledCommand(TuiControlId.Create(2), 'Save', TuiAction.Create(20)),
                                                                                                                      TuiStatusItemBuilders.MakeCommand(TuiControlId.Create(3), 'Quit', TuiAction.Create(30))
                                                                                                                    ])
                                                                                ])
end;

function UpdateStatus(State: StatusModel; Msg: TuiMsg; Cmd: TuiCmdOutput): StatusModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.FocusChanged(Previous, Current):
    begin
      case Current of
        Some(Id):
        begin
          return record
            Focus := Id.Value;
            Actions := State.Actions;
          end
        end;
        None:
        begin
          return State
        end
      end
    end;
    TuiMsg.Action(Source, Action):
    begin
      return record
        Focus := State.Focus;
        Actions := Std.Arrays.Concat(State.Actions, [Action.Value]);
      end
    end
    else
    begin
      return State
    end
  end
end;

begin
  mutable var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(24, 4));
  mutable var Model: StatusModel := record
    Focus := 3;
    Actions := [];
  end;

  Model := App.RunIterations(Model, UpdateStatus, ViewStatus, 0, 0);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Enter));
  Model := App.RunIterations(Model, UpdateStatus, ViewStatus, 1, 0);
  AssertEquals(1, Std.Arrays.Length(Model.Actions));
  AssertEquals(30, Model.Actions[0]);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Tab));
  Model := App.RunIterations(Model, UpdateStatus, ViewStatus, 1, 0);
  AssertEquals(3, Model.Focus);
  App.Close()
end.
